import std/syncio

proc readConfig(filename: string): string =
  try:
    let f = open(filename, fmRead)
    defer: f.close()
    result = f.readAll()
  except IOError as e:
    result = "Error reading config: " & e.msg

when isMainModule:
  let content = readConfig("non_existent_config.ini")
  echo content

import std/strutils

proc parseIntSafe(input: string, defaultVal: int): int =
  try:
    result = parseInt(input)
  except ValueError:
    echo "Invalid integer format, using default."
    result = defaultVal

when isMainModule:
  let parsed = parseIntSafe("abc12", 42)
  echo "Parsed value: ", parsed

import std/[syncio, strutils]

proc readIntFromFile(filename: string): int =
  try:
    let f = open(filename, fmRead)
    defer: f.close()
    let content = f.readAll()
    result = parseInt(content.strip())
  except IOError:
    echo "Could not read file."
    result = -1
  except ValueError:
    echo "File does not contain a valid integer."
    result = -2

when isMainModule:
  let val = readIntFromFile("missing_numbers.txt")
  echo "Result: ", val

type DatabaseError = object of CatchableError

proc connectDb(connString: string) =
  if connString == "":
    raise newException(DatabaseError, "Connection string cannot be empty")
  echo "Connected to ", connString

when isMainModule:
  try:
    connectDb("")
  except DatabaseError as e:
    echo "DB Connection Failed: ", e.msg

proc safeGetFirst(arr: openArray[int]): int =
  try:
    result = arr[0]
  except IndexDefect:
    echo "Array is empty! Returning 0."
    result = 0

when isMainModule:
  let emptySeq: seq[int] = @[]
  let val = safeGetFirst(emptySeq)
  echo "First value: ", val

import std/times

proc parseMyDate(dateStr: string): DateTime =
  try:
    result = parse(dateStr, "yyyy-MM-dd")
  except CatchableError as e:
    echo "Failed to parse date: ", e.name, " - ", e.msg
    result = now()

when isMainModule:
  let dt = parseMyDate("2024-invalid-15")
  echo "Parsed Date: ", dt.format("yyyy-MM-dd")

import std/strutils

proc processData(data: string) =
  try:
    let val = parseInt(data)
    echo "Processing ", val
  except ValueError:
    echo "[LOG] Encountered ValueError while processing data."
    raise # Reraise the exception

when isMainModule:
  try:
    processData("bad_data")
  except ValueError:
    echo "Caught reraised ValueError in main."

proc riskyAddition(a, b: int): int =
  try:
    result = a + b
  except OverflowDefect:
    echo "Arithmetic overflow detected!"
    result = int.high

when isMainModule:
  let maxInt = int.high
  let sum = riskyAddition(maxInt, 1)
  echo "Sum is: ", sum

import std/[syncio, strutils]

proc readAndParse() =
  try:
    let f = open("some_data.txt", fmRead)
    defer: f.close()
    let line = f.readLine()

    try:
      let num = parseInt(line)
      echo "Number is: ", num
    except ValueError:
      echo "Inner: Line is not a number."

  except IOError:
    echo "Outer: Could not read file."

when isMainModule:
  readAndParse()

import std/strutils

proc doSomethingRisky(s: string) =
  try:
    let x = parseInt(s)
    echo "Got ", x
  except:
    let e = getCurrentException()
    let msg = getCurrentExceptionMsg()
    echo "An exception of type ", e.name, " occurred."
    echo "Message: ", msg

when isMainModule:
  doSomethingRisky("not an int")

type
  AuthError = object of CatchableError
  TimeoutError = object of CatchableError

proc authenticate(token: string) =
  if token == "":
    raise newException(AuthError, "Missing authentication token")
  if token == "slow":
    raise newException(TimeoutError, "Authentication service timed out")
  echo "Authenticated successfully!"

when isMainModule:
  for t in ["", "slow", "valid"]:
    try:
      authenticate(t)
    except AuthError as e:
      echo "Auth issue: ", e.msg
    except TimeoutError as e:
      echo "Timeout issue: ", e.msg

import std/strutils

proc parseId(s: string): int =
  try:
    result = parseInt(s)
  except ValueError as e:
    e.msg = "Failed to parse ID: " & e.msg
    raise e

when isMainModule:
  try:
    discard parseId("abc")
  except ValueError as e:
    echo "Final error: ", e.msg

proc safeDivideFloat(a, b: float): float =
  try:
    if b == 0.0:
      raise newException(FloatInvalidOpDefect, "Division by zero")
    result = a / b
  except FloatInvalidOpDefect as e:
    echo "Float math error: ", e.msg
    result = 0.0

when isMainModule:
  let res = safeDivideFloat(5.0, 0.0)
  echo "Result: ", res
